const { PrismaClient } = require('@prisma/client')
const prisma = new PrismaClient()

async function main() {
  const purchaseId = 'cmqr0ie3h000ntjprncxymsds'
  const productId = 'cmqr0ie3w000ptjpr64bdej4j'

  console.log('Updating purchase item values...')
  await prisma.purchaseItem.updateMany({
    where: { purchaseId },
    data: {
      costPrice: 54.66,
      rate: 54.66,
      gstPercentage: 18
    }
  })

  console.log('Updating product values in catalog...')
  await prisma.product.update({
    where: { id: productId },
    data: {
      costPrice: 54.66,
      gstPercentage: 18
    }
  })

  console.log('Database correction completed successfully!')
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect())
